{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_h2",
        "intro_body",
        "divider_1",
        "key_aspects_h3",
        "causes_h3",
        "causes_intro_body",
        "militarism_card",
        "alliances_card",
        "imperialism_card",
        "nationalism_card",
        "assassination_card",
        "divider_2",
        "nations_h3",
        "nations_intro_body",
        "nations_table",
        "divider_3",
        "outcomes_h3",
        "outcomes_intro_body",
        "outcome_end_empires",
        "outcome_versailles",
        "outcome_league_nations",
        "outcome_new_nations",
        "outcome_casualties",
        "outcome_economic_devastation",
        "outcome_tech_advancements",
        "outcome_shifting_power",
        "divider_4",
        "quick_actions_h3",
        "quick_action_wikipedia_button",
        "quick_action_museum_button",
        "divider_5",
        "sources_h3",
        "source_wikipedia_button",
        "source_iwm_button"
      ]
    },
    "title_h2": {
      "type": "Text",
      "props": {
        "text": "World War I: A Global Conflict Overview",
        "variant": "h2"
      },
      "children": []
    },
    "intro_body": {
      "type": "Text",
      "props": {
        "text": "World War I (1914-1918), often called the \"Great War,\" was one of the deadliest conflicts in human history, fundamentally reshaping the geopolitical landscape of the 20th century."
      },
      "children": []
    },
    "divider_1": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "key_aspects_h3": {
      "type": "Text",
      "props": {
        "text": "Key Aspects of the Great War",
        "variant": "h3"
      },
      "children": []
    },
    "causes_h3": {
      "type": "Text",
      "props": {
        "text": "Causes of Conflict",
        "variant": "h3"
      },
      "children": []
    },
    "causes_intro_body": {
      "type": "Text",
      "props": {
        "text": "The war was ignited by a complex interplay of factors, often summarized by the acronym M.A.I.N.:"
      },
      "children": []
    },
    "militarism_card": {
      "type": "Card",
      "props": {},
      "children": [
        "militarism_text_stack"
      ]
    },
    "militarism_text_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "militarism_label",
        "militarism_body"
      ]
    },
    "militarism_label": {
      "type": "Text",
      "props": {
        "text": "Militarism:",
        "variant": "label"
      },
      "children": []
    },
    "militarism_body": {
      "type": "Text",
      "props": {
        "text": "An arms race and glorification of military power among European nations."
      },
      "children": []
    },
    "alliances_card": {
      "type": "Card",
      "props": {},
      "children": [
        "alliances_text_stack"
      ]
    },
    "alliances_text_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "alliances_label",
        "alliances_body",
        "alliances_triple_entente",
        "alliances_triple_alliance"
      ]
    },
    "alliances_label": {
      "type": "Text",
      "props": {
        "text": "Alliances:",
        "variant": "label"
      },
      "children": []
    },
    "alliances_body": {
      "type": "Text",
      "props": {
        "text": "A system of rigid defensive treaties creating two major blocs, forcing nations into conflict even if their direct interests weren't threatened."
      },
      "children": []
    },
    "alliances_triple_entente": {
      "type": "Text",
      "props": {
        "text": "• Triple Entente (Allies): France, Britain, Russia."
      },
      "children": []
    },
    "alliances_triple_alliance": {
      "type": "Text",
      "props": {
        "text": "• Triple Alliance (Central Powers): Germany, Austria-Hungary, Italy (initially, but later joined the Allies)."
      },
      "children": []
    },
    "imperialism_card": {
      "type": "Card",
      "props": {},
      "children": [
        "imperialism_text_stack"
      ]
    },
    "imperialism_text_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "imperialism_label",
        "imperialism_body"
      ]
    },
    "imperialism_label": {
      "type": "Text",
      "props": {
        "text": "Imperialism:",
        "variant": "label"
      },
      "children": []
    },
    "imperialism_body": {
      "type": "Text",
      "props": {
        "text": "Competition among European powers for colonies and resources, leading to heightened tensions."
      },
      "children": []
    },
    "nationalism_card": {
      "type": "Card",
      "props": {},
      "children": [
        "nationalism_text_stack"
      ]
    },
    "nationalism_text_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "nationalism_label",
        "nationalism_body"
      ]
    },
    "nationalism_label": {
      "type": "Text",
      "props": {
        "text": "Nationalism:",
        "variant": "label"
      },
      "children": []
    },
    "nationalism_body": {
      "type": "Text",
      "props": {
        "text": "Intense patriotism and desires for self-determination, especially in multi-ethnic empires like Austria-Hungary and the Ottoman Empire."
      },
      "children": []
    },
    "assassination_card": {
      "type": "Card",
      "props": {},
      "children": [
        "assassination_text_stack"
      ]
    },
    "assassination_text_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "assassination_label",
        "assassination_body"
      ]
    },
    "assassination_label": {
      "type": "Text",
      "props": {
        "text": "Assassination:",
        "variant": "label"
      },
      "children": []
    },
    "assassination_body": {
      "type": "Text",
      "props": {
        "text": "The immediate spark was the assassination of Archduke Franz Ferdinand of Austria-Hungary by a Serbian nationalist in Sarajevo on June 28, 1914. This triggered a chain reaction through the alliance system."
      },
      "children": []
    },
    "divider_2": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "nations_h3": {
      "type": "Text",
      "props": {
        "text": "Primary Participating Nations",
        "variant": "h3"
      },
      "children": []
    },
    "nations_intro_body": {
      "type": "Text",
      "props": {
        "text": "The conflict involved two main opposing alliances:"
      },
      "children": []
    },
    "nations_table": {
      "type": "Table",
      "props": {
        "domain": "comparison",
        "preferredPresentation": "cards",
        "columns": [
          {
            "key": "alliance",
            "label": "Alliance"
          },
          {
            "key": "members",
            "label": "Members"
          }
        ],
        "rows": [
          {
            "alliance": "Allied Powers (Triple Entente and its associates)",
            "members": "France\nBritish Empire (including Canada, Australia, New Zealand, India, South Africa)\nRussia (until 1917)\nItaly (from 1915)\nUnited States (from 1917)\nSerbia\nBelgium\nJapan\nOther nations including Romania, Greece, Portugal"
          },
          {
            "alliance": "Central Powers (Triple Alliance and its associates)",
            "members": "German Empire\nAustro-Hungarian Empire\nOttoman Empire\nBulgaria"
          }
        ]
      },
      "children": []
    },
    "divider_3": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "outcomes_h3": {
      "type": "Text",
      "props": {
        "text": "Major Outcomes",
        "variant": "h3"
      },
      "children": []
    },
    "outcomes_intro_body": {
      "type": "Text",
      "props": {
        "text": "The war concluded with significant and lasting consequences:"
      },
      "children": []
    },
    "outcome_end_empires": {
      "type": "Text",
      "props": {
        "text": "• End of Empires: The Austro-Hungarian, Ottoman, Russian, and German Empires collapsed."
      },
      "children": []
    },
    "outcome_versailles": {
      "type": "Text",
      "props": {
        "text": "• Treaty of Versailles: Imposed harsh terms on Germany, including territorial losses, reparations, and military restrictions, which contributed to resentment and future conflict."
      },
      "children": []
    },
    "outcome_league_nations": {
      "type": "Text",
      "props": {
        "text": "• League of Nations: Established to promote international cooperation and prevent future wars, though ultimately it failed to prevent World War II."
      },
      "children": []
    },
    "outcome_new_nations": {
      "type": "Text",
      "props": {
        "text": "• New Nations: Creation of new states in Central and Eastern Europe (e.g., Poland, Czechoslovakia, Yugoslavia) and the Middle East."
      },
      "children": []
    },
    "outcome_casualties": {
      "type": "Text",
      "props": {
        "text": "• Massive Casualties: Estimated 15-22 million deaths, both military and civilian, and millions more wounded."
      },
      "children": []
    },
    "outcome_economic_devastation": {
      "type": "Text",
      "props": {
        "text": "• Economic Devastation: Widespread destruction, immense war debts, and economic disruption across Europe."
      },
      "children": []
    },
    "outcome_tech_advancements": {
      "type": "Text",
      "props": {
        "text": "• Technological Advancements: Accelerated development of new weapons and military tactics (tanks, chemical warfare, aircraft)."
      },
      "children": []
    },
    "outcome_shifting_power": {
      "type": "Text",
      "props": {
        "text": "• Shifting Global Power: Decline of European dominance and the rise of the United States as a major world power."
      },
      "children": []
    },
    "divider_4": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "quick_actions_h3": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "quick_action_wikipedia_button": {
      "type": "Button",
      "props": {
        "label": "Explore WWI on Wikipedia"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://en.wikipedia.org/wiki/World_War_I"
          }
        }
      },
      "children": []
    },
    "quick_action_museum_button": {
      "type": "Button",
      "props": {
        "label": "Visit Imperial War Museums"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.iwm.org.uk/"
          }
        }
      },
      "children": []
    },
    "divider_5": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "sources_h3": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "source_wikipedia_button": {
      "type": "Button",
      "props": {
        "label": "Wikipedia: World War I"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://en.wikipedia.org/wiki/World_War_I"
          }
        }
      },
      "children": []
    },
    "source_iwm_button": {
      "type": "Button",
      "props": {
        "label": "Imperial War Museums"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.iwm.org.uk/"
          }
        }
      },
      "children": []
    }
  }
}
